import sys

def bfs(x, y, k):
    queue = deque([(x, y, 0)])
    visited = set()
    moves = {(0, 1), (1, 0), (0, -1), (-1, 0)}

    while queue:
        pos, key_pos, time_left = queue.popleft()

        if pos == key_pos:
            return time_left

        visited.add((pos, time_left))

        for dx, dy in moves:
            new_pos = pos[0] + dx, pos[1] + dy

            if new_pos not in visited and 0 <= new_pos[0] <= 100 and 0 <= new_pos[1] <= 100:
                queue.append((new_pos, key_pos, time_left + 1))

                if new_pos == (pos[0], pos[1]):
                    queue.append((new_pos, new_pos, time_left + 1))

                if 0 <= time_left + 1 <= k:
                    queue.append((new_pos, key_pos, time_left + 1))

    return -1

