from collections import Counter

def solve(n, s):
    count_a = Counter(s)
    if n % 2 == 0 and count_a['A'] > count_a['B']:
        return 'A'
    if n % 2 == 1 and count_a['A'] < count_a['B']:
        return 'B'
    if n % 2 == 0 and count_a['A'] == count_a['B']:
        return '?'
    if n % 2 == 1 and count_a['A'] - count_a['B'] == 1:
        return 'A'
    if n % 2 == 1 and count_a['B'] - count_a['A'] == 1:
        return 'B'
    return '?'

from collections import Counter
import re

def solve(n, s):
    if n == 1:
        return s[0]

    count_a = Counter(s)
    max_wins = max(count_a.values())
    if max_wins != count_a[s[0]]:
        return '?'

    wins_needed = min(count_a[s[0]], n // 2) + 1
    if wins_needed > max_wins:
        return '?'

    winning_run = re.search(r'(.)\1{%d}' % wins_needed, s)
    if not winning_run:
        return '?'

    winner = winning_run.group(1)
    if n % 2 == 0 and winner != s[0]:
        return '?'

    return winner

