import math

def solve():
    def update(bit, n, pos, val):
        while pos <= n:
            bit[pos] += val
            pos += pos & -pos

    def sum(bit, n, r):
        res = 0
        while r:
            res += bit[r]
            r -= r & -r
        return res

    def sort_array(a, n):
        bit = [0] * (n + 1)
        for i in range(1, n + 1):
            update(bit, n, i, -a[i - 1])
        for i in range(1, n + 1):
            m = math.log2(i) + 1
            a[i - 1] = max(a[i - 1], sum(bit, n, min(n, int(math.pow(2, m)))))
        return a

