def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve(n, a=None):
    if not a:
        a = [1]
    if len(a) == n:
        return a

    for candidate in range(a[-1] + 1, min(10**9, 3 * a[-2] // (a[-1] + a[-2] - a[-1]))):
        if gcd(candidate, a[-1] + a[-2]) != 1:
            continue
        a.append(candidate)
        if gcd(3 * a[-1], a[-2] + a[-1]) != 1:
            continue
        result = solve(n, a)
        if result:
            return result
        a.pop()

    # If no solution is found, return an array of ones
    return [1] * n

