from collections import defaultdict
from functools import lru_cache

def sieve_of_eratosthenes(n):
    primes = [True] * (n + 1)
    primes[0], primes[1] = False, False
    for i in range(2, int(n ** 0.5) + 1):
        if primes[i]:
            for j in range(i * i, n + 1, i):
                primes[j] = False
    return primes

@lru_cache(maxsize=None)
def mex(n, primes):
    if n in primes:
        return n
    return mex(n - 1, primes) + 1

def solve(n, k, x):
    primes = sieve_of_eratosthenes(x)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            if primes[j]:
                dp[i] = max(dp[i], dp[i - j] + j)
    if dp[-1] > k:
        return -1
    return dp[-1]

from 2 to `n+1`, we iterate from `k` to `x` and update `dp[i]` as the maximum of `dp[i]`, `dp[i - k] + j` (if `dp[i - k]` is not `-1`), and `j` (if `i - k` is greater than `i`). Finally, we return the maximum value in `dp[n:]`.

