from collections import defaultdict

def solve(p):
    n = len(p)
    graph = defaultdict(list)
    for i in range(n):
        graph[p[i]].append(i+1)

    def dfs(index, count):
        if count == n:
            return True
        for i in range(1, n+1):
            if i not in graph[index] and dfs(graph[index][0], count+1):
                for j in range(1, len(graph[index])):
                    graph[graph[index][j]].remove(index)
                    graph[index] = [graph[index][0]]
                    if dfs(graph[index][0], count+1):
                        return True
                graph[index] = graph[index][1:]
        return False

    for i in range(1, n+1):
        if dfs(i, 1):
            return 1
    return -1

