            heap = [(abs(arr[i] - i) for i in range(len(arr))]
            heapq.heapify(heap)
            operations = 0
            while heap:
                diff = heapq.heappop(heap)
                if diff > 1:
                    operations += diff - 1
                    heapq.heappush(heap, 1)
            print(operations)

