import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def prime_divisors(n):
    divisors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            divisors.append(i)
    if n > 1:
        divisors.append(n)
    return divisors

def solve(x, k):
    if k == 1:
        return 1, [1 * sign for sign in [1, -1] if x % sign != 0]

    divisors = prime_divisors(k)
    for d in divisors:
        if x % d == 0:
            q = x // d
            r = q * d - x
            if r and gcd(r, k) == 1:
                moves, jumps = q + solve(r, k)[0], solve(r, k)[1]
                return moves, [jump for jump in jumps if jumps[0] * d + jumps[1] * (q - 1) <= x < jumps[0] * d + jumps[1] * q]

    # If k is not a prime number and there is no divisor of x, we can use binary search to find the smallest number of moves
    left, right = 1, math.inf
    while left < right:
        mid = (left + right) // 2
        if mid * k <= x:
            left = mid + 1
        else:
            right = mid
    return right, [i * sign for i in range(1, right) for sign in [1, -1] if x % (i * k) != 0]

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def prime_factorization(n):
    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def next_prime(n):
    if n % 2 == 0:
        n += 1
    while True:
        n += 2
        is_prime = True
        for p in prime_factorization(n - 4):
            if n % p == 0:
                is_prime = False
                break
        if is_prime:
            break
    return n

