from collections import defaultdict

def solve():
    def find_twin_permutation():
        n = int(input())
        a = list(map(int, input().split()))
        visited = defaultdict(int)
        slow, fast = 0, 0

        while fast < n:
            visited[a[fast]] += 1
            fast = (a[fast] - 1) % n
            visited[fast] += 1

            if visited[fast] > 1:
                slow = fast

            if slow == fast:
                break

        b = [0] * n
        i = 0
        for j in range(n):
            if a[j] != fast + 1:
                b[i] = a[j]
                i += 1
            fast = (fast + 1) % n

        for j in range(n, 0, -1):
            if a[j - 1] != fast + 1:
                b[i] = fast + 1
                i += 1
            fast = (fast + n - 1) % n

        return b

    t = int(input())
    for _ in range(t):
        print(*find_twin_permutation())

