    dp = [[0] * 2 for _ in range(n)]
    dp[0][0] = dp[0][1] = 1

    for i in range(1, n):
        dp[i][0] = dp[i - 1][0] + dp[i - 1][1]
        dp[i][1] = dp[i - 1][0]

    for i in range(2, n):
        for j in range(i, 0, -1):
            dp[j][1] += dp[j + i][0]

    if dp[n - 1][1] < k:
        print("NO")
