def solve(n, k):
    if k > (n - 1) * n // 2 or k < 0:
        return "NO"

    # Count the number of elements with odd count of 1's in their binary representation
    odd_count = defaultdict(int)
    for i in range(1, int(sqrt(n)) + 1):
        if n % i == 0:
            odd_count[i] += n // i
            odd_count[n // i] += i

    # Check if the remaining elements can form pairs with the elements already found
    remaining = n - sum(odd_count.values())
    if remaining % 2 != k:
        return "NO"
    pairs = min(remaining // 2, k)

    # Generate the array
    a = [1]
    for _ in range(1, n):
        a.append(-1 if a[-1] == 1 else 1)
        if len(a) - pairs > 1:
            a[::-1].pop()
            break

    return "YES\n" + "\n".join(map(str, a))

