from itertools import combinations

def solve(n, k, members):
    # Create a dictionary to store the number of agreements and disagreements for each opinion
    counts = defaultdict(lambda: [0, 0])
    for member in members:
        for i in range(k):
            if member[i] == '+':
                counts[i][0] += 1
            else:
                counts[i][1] += 1

    # Find the opinions with the minimum number of agreements and maximum number of disagreements
    min_agree, max_disagree = float('inf'), -float('inf')
    for count in counts.values():
        min_agree = min(min_agree, count[0])
        max_disagree = max(max_disagree, count[1])

    # If there is a tie, return 0 as no members can stay
    if min_agree == max_disagree:
        return 0

    # Find the maximum number of members that can stay by considering all possible subsets of members
    max_members = 1
    for subset in combinations(range(1, n+1), n-1):
        # Check if the subset agrees on all opinions except the one with the minimum number of agreements
        if all(members[i][min_agree-1] == '+' for i in subset):
            # Check if the remaining member disagrees on the opinion with the maximum number of disagreements
            if members[n] != members[subset[0]][max_disagree-1]:
                max_members = max(max_members, len(subset) + 1)

    return max_members

from collections import Counter

def solve(n, k, members):
    # Initialize a counter to keep track of the number of agreements and disagreements for each opinion
    counts = Counter()
    for member in members:
        for opinion in member:
            counts[opinion] += 1

    # Find the opinions with the minimum number of agreements and disagreements
    min_agree, min_disagree = float('inf'), float('inf')
    for opinion, count in counts.items():
        if count > 0:
            min_agree = min(min_agree, count)
        if count > 0:
            min_disagree = min(min_disagree, n - count)

    # If there is a tie, return 0 as no members can stay
    if min_agree == min_disagree:
        return 0

    # Calculate the maximum number of members that can stay
    max_members = min(min_agree, min_disagree) + 1

    # Return the maximum number of members that can stay, including the president
    return max_members + 1

