from typing import List

def solve():
    def max_insert_digit(num: str, digit: int) -> str:
        @functools.lru_cache(maxsize=None)
        def dp(i: int) -> int:
            if i == len(num) + 1:
                return 0
            if i == len(num):
                return 10 * digit + int(num)
            return max(
                dp(i + 2) + (10 * digit + int(num[i:])),
                dp(i + 1) + (10 * digit + int(num[:i]) + int(num[i]))
            )
        return str(dp(1) + digit)

