from collections import deque

def beautiful_sequence(arr):
    q = deque()
    visited = set()
    for i in arr:
        if i not in visited:
            q.append(i)
            visited.add(i)
        elif q and q[0] == i:
            q.popleft()
    return len(q) > 0

