    visited = [0] * n
    queue = deque([(i, 0) for i in range(n) if colors[i] != visited[0]])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        bulb, count = queue.popleft()
        if visited[bulb] == colors[bulb]:
            continue
        visited[bulb] = colors[bulb]
        if all(visited == colors):
            return count + 1
        for dx, dy in directions:
            next_bulb = (bulb + dx * n + dy) % n
            if not visited[next_bulb] and colors[next_bulb] != visited[bulb]:
                queue.append((next_bulb, count + 1))

    return -1

