def solve():
    t = int(input())
    for _ in range(t):
        n, s, r = map(int, input().split())
        res = [1] * (n - 1) + [s - r]
        for i in range(1, 7):
            for c in combinations(range(n - 1), i):
                temp = list(res)
                for j in c:
                    temp[j] += 1
                if sum(temp) == s:
                    print(*temp)
                    break
            else:
                continue
            break
        else:
            print(*res)

