import math

def solve():
    w, d, h = map(int, input().split())
    a, b, f, g = map(int, input().split())
    ans = h + min(abs(a-f) + min(b, g, d-g, w-f, w-a)
    if a + b <= f + g:
        ans += min(a, f) + min(b, g)
    else:
        ans += min(a, w-f) + min(d-b, d-g)
    return ans

