import heapq

def solve():
    input = sys.stdin.readline
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = list(map(int, input().split()))
        pq = []
        for i in range(n):
            heapq.heappush(pq, s[i])
        max1 = heapq.heappop(pq)
        max2 = heapq.heappop(pq)
        for i in range(n):
            if s[i]!= max1:
                print(s[i] - max1, end=' ')
            else:
                print(s[i] - max2, end=' ')
        print()

