def solve():
    input = sys.stdin.readline
    t = int(input.strip())
    for _ in range(t):
        m, s = map(int, input().split())
        b = list(map(int, input().split()))
        b_set = set(b)
        max_num = max(b)
        total = sum(b)
        s += total
        for i in range(1, max_num + 1):
            if i not in b_set:
                if s - i == 0:
                    print("YES")
                    break
                elif s - i > 0:
                    s -= i
        else:
            print("NO")

