def solve():
    input = sys.stdin.readline
    t = int(input.strip())
    for _ in range(t):
        m,s = map(int,input().strip().split())
        b = list(map(int,input().strip().split()))
        b_set = set(b)
        max_num = max(b)
        total_sum = sum(b)
        total_sum += s
        if total_sum > (max_num * (max_num + 1)) // 2:
            print("NO")
        else:
            for i in range(1,max_num + 1):
                if i not in b_set:
                    total_sum -= i
                    if total_sum == s:
                        print("YES")
                        break
            else:
                print("NO")

