from collections import deque

def solve():
    input = sys.stdin.readline
    t = int(input().strip())
    for _ in range(t):
        n, k = map(int, input().split())
        a = deque(map(int, input().split()))
        while len(a) > 1:
            if a[0] == 0:
                a.popleft()
            elif a[-1] == 0:
                a.pop()
            elif k > 1 and len(a) >= k:
                for i in range(k):
                    a.popleft()
            else:
                break
        if len(a) == 1 and a[0] == 1:
            print("YES")
        else:
            print("NO")

