def solve():
    t = int(input())
    for _ in range(t):
        n, q = map(int, input().split())
        a = list(map(int, input().split()))
        even_sum = sum(x for x in a if x % 2 == 0)
        odd_sum = sum(x for x in a if x % 2!= 0)
        for _ in range(q):
            type_j, x_j = map(int, input().split())
            if type_j == 0:
                even_sum += x_j * (n - (odd_sum + even_sum) // 2)
            else:
                odd_sum += x_j * (odd_sum + even_sum) // 2
            print(odd_sum + even_sum)

