                print('<')
            else:
                print('=')

import re

def solve():
    sizes = {"S": 0, "M": 1, "L": 2}
    patterns = {
        r"^[X]*S$": lambda x: (0, -len(re.findall(r"[X]*", x)),
        r"^[X]*M$": lambda x: (1, -len(re.findall(r"[X]*", x)),
        r"^[X]*L$": lambda x: (2, -len(re.findall(r"[X]*", x))
    }

    def compare(a, b):
        a_size = sizes.get(a[-1], -1)
        b_size = sizes.get(b[-1], -1)

        if a_size!= b_size:
            return "<" if a_size < b_size else ">"

        a_degree = patterns.get(re.compile(f"^{a[-1]}$"), a)
        b_degree = patterns.get(re.compile(f"^{b[-1]}$"), b)

        if a_degree!= b_degree:
            return "<" ifa_degree < b_degree else ">"

        return "="

    t = int(input())
    for _ in range(t):
        a, b = input().split()
        print(compare(a, b))

