def solve():
    t = input()
    result = []
    while t:
        match = re.match(r'(\d{1,2})0|(\d)', t)
        if match.group(1):
            result.append(chr(int(match.group(1) + 96))
        else:
            result.append(chr(int(match.group(2) + 96))
        t = t[match.end():]
    return ''.join(result)

