def solve():
    s = [input() for _ in range(2)]
    s = [list(row) for row in s]
    colors = set(s[0] + s[1])
    if len(colors) == 1:
        return 0
    elif len(colors) == 2:
        if s[0][0] == s[1][1] or s[0][1] == s[1][0]:
            return 1
        else:
            return 2
    else:
        return math.ceil(len(colors) / 2)

