from collections import deque

def solve():
    input = sys.stdin.readline
    t = int(input().strip())
    for _ in range(t):
        n, m = map(int, input().split())
        a = deque(input().strip())
        b = input().strip()
        while len(a) > m:
            if a[0] == b[0]:
                a.popleft()
            elif a[0] < b[0]:
                a[1] = min(a[0], a[1])
                a.popleft()
            else:
                a[1] = max(a[0], a[1])
                a.popleft()
        if ''.join(a) == b:
            print("YES")
        else:
            print("NO")

