                    break
            if len(q) == 0:
                res.append((a[i] - b) % 10)
            else:
                res.append((a[i] - b + sum(q)) % 10)
        print(*res)

from collections import defaultdict

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input()
        mp = defaultdict(int)
        ans = 0
        for i in s:
            if mp[i] == 0:
                ans += 2
            else:
                ans += 1
            mp[i] += 1
        print(ans)

